// Нода 1: Валидация входящего запроса от EPICGRAM
// Webhook body в n8n доступен прямо в $json (не $json.body)
const item = $input.first().json;

// Поддержка двух форматов: прямой body или вложенный в body
const body = (item.body && typeof item.body === 'object') ? item.body : item;

// Проверяем обязательные поля
const required = ['workspace_id', 'chat_id', 'messages', 'task'];
for (const field of required) {
  if (body[field] === undefined || body[field] === null) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Принимаем любой task (prepare_reply и другие)
const messages = Array.isArray(body.messages) ? body.messages : [];
const lastMessages = messages.slice(-10); // берём последние 10

return [{
  json: {
    workspace_id: body.workspace_id,
    chat_id: body.chat_id,
    chat_title: body.chat_title || 'Unknown Chat',
    task: body.task,
    messages: lastMessages,
    message_count: messages.length,
    validated_at: new Date().toISOString()
  }
}];
